sys_script_include.script:
var PanoramaLogger = Class.create();
PanoramaLogger.prototype = Object.extendsObject(global.GSLog, {
	initialize: function(traceProperty, caller) {
		global.GSLog.prototype.initialize.call(this, traceProperty, caller);
	},

	debug: function(msg) {
        this.logDebug("[Panorama] " + msg);
    },

    error: function(msg) {
        this.logError("[Panorama] " + msg);
    },

    info: function(msg) {
        this.logInfo("[Panorama] " + msg);
    },

    _createIncident: function(msg, response) {
        try {
            var body = response.getBody();
            var parsed;
            try {
                parsed = JSON.parse(body);
            } catch (e) {
                parsed = null;
            }

            var desc = [];
            desc.push("Message: " + msg);
            desc.push("HTTP Status: " + response.getStatusCode());
            if (parsed) {
                desc.push("Error Code: " + parsed.code);
                desc.push("Error Message: " + parsed.message);
                if (parsed.details)
                    desc.push("Details:" + this._extractErrorDetails(parsed));
            } else {
                desc.push("Raw Body:" + body);
            }

            var inc = new GlideRecord("incident");
            inc.initialize();
            inc.setValue("short_description","Panorama API Error Encountered: Error Code: " + parsed.code);
            inc.setValue("description", desc.join(" "));
			// inc.setValue("assignment_group", "");
			// inc.setValue('category', 'request');
			// inc.setValue('u_category', 'software');
			// inc.setValue('subcategory', 'functionality');
			// inc.setValue('caller_id', ''); //Panorama Int Admin
            var incSysId = inc.insert();
			inc.update();
			return incSysId;
        } catch (e) {
            this.error("PanoramaLogger failed to create incident: " + e);
        }
    },

    _extractErrorDetails: function(parsed) {
        if (!parsed || !parsed.details) return "No details available.";
        var result = [];
        for (var i = 0; i < parsed.details.length; i++) {
            var causes = parsed.details[i].causes || [];
            for (var j = 0; j < causes.length; j++) {
                var c = causes[j];
                result.push("[" + (c.module || "unknown") + "] " + (c.description || ""));
            }
        }
        return result.join("\n");
    },

    type: "PanoramaLogger"
});
